(function(){try{
const META={"frost": {"fw": 184, "fh": 96, "cx": 92.5, "fy": 93, "bodyH": 92, "ic": [53, 1, 79, 92], "d": -1, "idle": [0, 6], "walk": [1, 10], "atk": [2, 14], "hurt": [3, 7], "death": [[4, 16]], "dt": [0.13, 0.08, 0.085]}, "dslime": {"fw": 210, "fh": 124, "cx": 126.0, "fy": 124, "bodyH": 105, "ic": [86, 19, 80, 105], "d": -1, "idle": [0, 6], "walk": [1, 12], "atk": [2, 15], "hurt": [3, 5], "death": [[4, 22]], "dt": [0.14, 0.08, 0.07]}, "mecha": {"fw": 71, "fh": 71, "cx": 25.0, "fy": 47, "bodyH": 46, "ic": [1, 1, 48, 46], "d": 1, "idle": [0, 4], "walk": [6, 10], "atk": [2, 9], "hurt": [5, 4], "death": [[7, 10], [8, 4]], "dt": [0.16, 0.09, 0.1]}, "sam": {"fw": 59, "fh": 35, "cx": 12.0, "fy": 34, "bodyH": 34, "ic": [2, 0, 20, 34], "d": 1, "idle": [0, 10], "walk": [1, 16], "atk": [2, 7], "hurt": [3, 4], "dt": [0.11, 0.06, 0.1]}, "pb1": {"st": 1, "w": 488, "h": 291, "ic": [0, 0, 488, 291]}, "pb2": {"st": 1, "w": 579, "h": 293, "ic": [0, 0, 579, 293]}, "pb3": {"st": 1, "w": 635, "h": 286, "ic": [0, 0, 635, 286]}, "pb4": {"st": 1, "w": 594, "h": 288, "ic": [0, 0, 594, 288]}},SRC={"frost": "", "dslime": "", "mecha": "", "sam": "", "pb1": "", "pb2": "", "pb3": "", "pb4": ""},MAP={"21": ["frost", 0], "23": ["frost", 25], "61": ["frost", 215], "17": ["frost", 235], "5": ["mecha", 0], "15": ["mecha", 200], "45": ["mecha", 40], "72": ["mecha", 170], "75": ["mecha", 300], "3": ["dslime", 100], "57": ["dslime", 20], "58": ["dslime", 60], "89": ["dslime", 185], "48": ["sam", 235], "49": ["sam", 335], "51": ["sam", 100], "9": ["pb2", 150], "35": ["pb2", 190], "65": ["pb2", 270], "80": ["pb2", 90], "82": ["pb2", 0], "85": ["pb1", 200], "93": ["pb1", 250], "98": ["pb1", 300], "99": ["pb3", 0], "83": ["pb3", 45], "26": ["pb4", 335], "79": ["pb4", 350], "97": ["pb4", 0]},STH='nnnueenunuppeeeercooiiiirrrrhhthnnuoopooooooeeeessnsrrrresseiiiivuvvhhttmmpmvrvvueuvhhvmphvvvvnthvvv';
const TH={n:[[110,220,90],[210,255,140],1,12],e:[[200,160,100],[130,105,75],3,10],p:[[150,220,60],[200,120,230],0,12],
u:[[150,255,200],[205,215,235],0,12],r:[[255,120,30],[255,220,80],0,16],i:[[140,210,255],[240,250,255],1,16],
o:[[80,170,255],[170,240,255],0,14],h:[[255,240,150],[255,255,255],0,14],t:[[255,230,90],[120,190,255],2,12,1],
v:[[170,70,255],[255,60,200],2,14],m:[[120,220,255],[255,170,60],2,10],s:[[255,140,170],[240,240,255],1,10],c:[[200,120,255],[120,230,255],2,12]};
const BX={img:{},cnt:0,ready:false,cache:new Map(),corpses:[]},NK=Object.keys(SRC).length;
const rg=(c,a)=>'rgba('+c[0]+','+c[1]+','+c[2]+','+Math.max(0,Math.min(1,a))+')';
const thOf=e=>{const d=ET[e.et];return TH[STH[(d&&d.si)|0]]||TH.n};
for(const k in SRC){const im=new Image();im.onload=()=>{if(++BX.cnt===NK)BX.ready=true};im.src='data:image/png;base64,'+SRC[k];BX.img[k]=im}
for(const s in MAP)NA_BOSS[s]=MAP[s];
for(const d of ET)delete d._na;
function sh(key,deg){const im=BX.img[key];deg=((Math.round(deg||0)%360)+360)%360;if(!deg)return im;
 const ck=key+':'+deg;let cv=BX.cache.get(ck);if(cv)return cv;
 cv=document.createElement('canvas');cv.width=im.width;cv.height=im.height;
 const c=cv.getContext('2d',{willReadFrequently:true});c.drawImage(im,0,0);
 const id=c.getImageData(0,0,cv.width,cv.height),d=id.data,a=deg*Math.PI/180,co=Math.cos(a),si=Math.sin(a);
 const m=[.213+co*.787-si*.213,.715-co*.715-si*.715,.072-co*.072+si*.928,.213-co*.213+si*.143,.715+co*.285+si*.14,.072-co*.072-si*.283,.213-co*.213-si*.787,.715-co*.715+si*.715,.072+co*.928+si*.072];
 for(let o=0;o<d.length;o+=4){if(!d[o+3])continue;const r=d[o],g=d[o+1],b=d[o+2];
  d[o]=Math.max(0,Math.min(255,r*m[0]+g*m[1]+b*m[2]));d[o+1]=Math.max(0,Math.min(255,r*m[3]+g*m[4]+b*m[5]));d[o+2]=Math.max(0,Math.min(255,r*m[6]+g*m[7]+b*m[8]))}
 c.putImageData(id,0,0);BX.cache.set(ck,cv);return cv}
/* gambar sprite: hidup / sekarat. e=boss (boleh null), df=[row,col] frame death */
function spr(cfg,Hh,fx,mode,st,t,flash,alpha,lv,e,df,T){
 const M=META[cfg.key],s=sh(cfg.key,cfg.deg);let dr;
 ctx.save();ctx.globalAlpha=alpha;
 if(M.st){
  const h=Hh*1.25,w=h*M.w/M.h;let ox=0,oy=-10+Math.sin(t*2.4)*4,rot=0,kx=1+Math.sin(t*2.4)*.012,ky=1-Math.sin(t*2.4)*.012;
  if(mode==='walk'){oy+=Math.sin(t*9)*2;rot=Math.sin(t*5)*.05}
  else if(mode==='atk'){const L=Math.sin(Math.min(1,st.age/.32)*Math.PI);ox=fx*L*14;oy-=L*6;kx=1+L*.18;ky=1-L*.1}
  else if(mode==='hurt')ox=Math.sin(st.age*70)*4;
  ctx.imageSmoothingEnabled=true;ctx.translate(ox,Hh/2+oy);ctx.rotate(rot);ctx.scale(kx,ky);
  dr=()=>ctx.drawImage(s,-w/2,-h,w,h);
 }else{
  let rn,f;
  if(df){rn=df[0];f=df[1]}
  else if(mode==='atk'){rn=M.atk[0];const n=M.atk[1],p=e&&e._bxCa&&e.castTimer>0?1-e.castTimer/e._bxCa:Math.min(1,st.age/.32);f=Math.min(n-1,Math.floor(Math.max(0,p)*n))}
  else if(mode==='hurt'&&M.hurt){rn=M.hurt[0];f=Math.min(M.hurt[1]-1,Math.floor(st.age/.05))}
  else if(mode==='walk'){rn=M.walk[0];f=Math.floor(t/M.dt[1])%M.walk[1]}
  else{rn=M.idle[0];f=Math.floor(t/M.dt[0])%M.idle[1]}
  const sc=Hh/M.bodyH;ctx.imageSmoothingEnabled=false;ctx.scale(fx*M.d,1);
  dr=()=>ctx.drawImage(s,f*M.fw,rn*M.fh,M.fw,M.fh,-M.cx*sc,Hh/2-M.fy*sc,M.fw*sc,M.fh*sc);
 }
 dr();
 if(flash){ctx.globalCompositeOperation='lighter';ctx.globalAlpha=flash*alpha;dr()}
 if(lv&&T){ctx.globalCompositeOperation='lighter';ctx.globalAlpha=alpha*.1*lv*(.6+.4*Math.sin(t*7));dr()}
 ctx.restore()}
function bxDraw(e,cfg){
 if(!BX.ready)return false;
 const Hh=Math.max(84,e.r*2.7);let mode=trpgState(e,1);const st=e._ta;
 if(e.castTimer>0){if(!e._bxCa)e._bxCa=e.castTimer;if(mode!=='hurt')mode='atk'}else e._bxCa=0;
 spr(cfg,Hh,st.fx,mode,st,worldTime+st.off,e.hit>0?.45:0,1,e.bossPhase|0,e,null,1);return true}
/* aura latar: partikel sesuai tema (tanpa alokasi array) */
function bxBack(e,T){
 const t=worldTime,lv=e.bossPhase|0,r=e.r*1.5,n=T[3]+lv*5,c1=T[0],c2=T[1],mode=T[2];
 ctx.save();ctx.translate(Math.round(e.x),Math.round(e.y));
 ctx.save();ctx.translate(0,14);ctx.scale(1,.34);
 const g=ctx.createRadialGradient(0,0,2,0,0,r*1.7);g.addColorStop(0,rg(c1,.38+.1*lv+.08*Math.sin(t*3)));g.addColorStop(1,rg(c1,0));
 ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r*1.7,0,6.283);ctx.fill();ctx.restore();
 for(let i=0;i<n;i++){
  const u=i/n,ph=(t*(.25+(i%3)*.08+lv*.08)+u*7.13)%1,q=(i*.6180339)%1;let x,y,al,s=2+(i%3);
  if(mode===0){x=Math.cos(i*2.4)*r*(.25+.75*q);y=16-ph*r*2;al=Math.sin(ph*3.1416)}
  else if(mode===1){x=(q-.5)*r*2.6+Math.sin(t*1.5+i)*7;y=-r*1.5+ph*r*2.4;al=Math.sin(ph*3.1416)}
  else if(mode===2){const a=u*6.283+t*(.9+lv*.4);x=Math.cos(a)*r*1.2;y=Math.sin(a)*r*.45-r*.25;al=.55+.4*Math.sin(a)}
  else{x=(q-.5)*r*2.4;y=16-ph*r*.5;al=.6*Math.sin(ph*3.1416);s+=2}
  ctx.fillStyle=rg(i%2?c2:c1,al*.9);ctx.fillRect(x|0,y|0,s,s)}
 if(T[4]&&(t*1.4)%1<.1){const k=Math.floor(t*1.4);let x=((k*73)%100-50)*e.r/40,y=-260;
  ctx.strokeStyle=rg(c2,.9);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);
  for(let j=0;j<8;j++){x+=((k*31+j*17)%21-10)*1.6;y+=34;ctx.lineTo(x,y)}ctx.stroke()}
 ctx.restore()}
/* efek depan: telegraph skill, gelombang serangan, transisi fase */
function bxFront(e,T){
 const t=worldTime,lv=e.bossPhase|0,b=e._bx||(e._bx={r:[],sf:0,ph:lv,cs:false,ca:0}),sf=e.skillFlash||0,cast=e.castTimer>0;
 if(sf>b.sf+.2||(cast&&!b.cs)){b.r.push({t0:t,big:0});burst(e.x,e.y+10,rg(T[0],1),10,{spd:150})}
 if(cast&&!b.ca)b.ca=e.castTimer;if(!cast)b.ca=0;
 b.sf=sf;b.cs=cast;
 if(lv!==b.ph){b.ph=lv;b.r.push({t0:t,big:1},{t0:t+.18,big:1});burst(e.x,e.y,rg(T[1],1),36,{spd:260,life:[.4,1]})}
 ctx.save();ctx.translate(Math.round(e.x),Math.round(e.y));
 if(cast){const p=b.ca?1-e.castTimer/b.ca:.5;
  ctx.strokeStyle=rg(T[0],.35+.35*Math.sin(t*14));ctx.lineWidth=2;ctx.beginPath();
  ctx.ellipse(0,14,e.r*(2.2-p*.9),e.r*(.7-p*.2),0,0,6.283);ctx.stroke();
  for(let i=0;i<8;i++){const a=i/8*6.283+t,d=e.r*(2.4-((t*1.6+i/8)%1)*2.1);ctx.fillStyle=rg(T[i%2],.8);ctx.fillRect((Math.cos(a)*d)|0,(Math.sin(a)*d*.5-4)|0,3,3)}}
 for(let i=b.r.length-1;i>=0;i--){const f=b.r[i],a=t-f.t0;if(a>1.1){b.r.splice(i,1);continue}if(a<0)continue;
  const k=a/1.1,R=e.r*(1+k*(f.big?6:3.5));
  ctx.strokeStyle=rg(T[f.big?1:0],(1-k)*.9);ctx.lineWidth=(f.big?5:3)*(1-k)+1;ctx.beginPath();ctx.ellipse(0,14,R,R*.36,0,0,6.283);ctx.stroke();
  if(f.big){ctx.strokeStyle=rg(T[0],(1-k)*.6);ctx.beginPath();ctx.ellipse(0,14,R*.7,R*.25,0,0,6.283);ctx.stroke()}}
 ctx.restore()}
const _de=window.drawEnemy;
window.drawEnemy=function(e){
 if(!e.boss)return _de(e);
 let T=null;
 try{const c=bossCutscene;if(!(c.active&&c.boss===e&&c.intro<=0)){T=thOf(e);bxBack(e,T)}}catch(_){T=null}
 _de(e);
 try{if(T)bxFront(e,T)}catch(_){}};
/* kematian boss: animasi death + ledakan sesuai tema */
const _nsc=window.naSpawnCorpse;
window.naSpawnCorpse=function(e){const c=naCfgOf(e);if(c&&META[c.key]&&e.boss)return true;return _nsc(e)};
const _stc=window.spawnTrpgCorpse;
window.spawnTrpgCorpse=function(e){
 try{if(e.boss){const T=thOf(e),c=naCfgOf(e),M=c&&META[c.key],cfg=M&&BX.ready?c:null;
  let fr=null,life=1.6;if(cfg&&M.death){fr=[];for(const [r,n] of M.death)for(let j=0;j<n;j++)fr.push([r,j]);life=Math.max(1.6,fr.length*M.dt[2]+.8)}
  if(BX.corpses.length>6)BX.corpses.shift();
  BX.corpses.push({cfg,fr,x:e.x,y:e.y,r:e.r,T,t0:worldTime,life,fx:e._ta?e._ta.fx:(player.x>=e.x?1:-1)});
  burst(e.x,e.y,rg(T[0],1),44,{spd:250,life:[.5,1.3]});burst(e.x,e.y,rg(T[1],1),26,{spd:150,life:[.4,1]});addShake(7)}}catch(_){}
 return _stc(e)};
function bxCorpses(){
 for(let i=BX.corpses.length-1;i>=0;i--){const c=BX.corpses[i],age=worldTime-c.t0;
  if(age<0||age>c.life){BX.corpses.splice(i,1);continue}
  if(c.x<camX-300||c.x>camX+W+300||c.y<camY-300||c.y>camY+H+300)continue;
  const T=c.T;ctx.save();ctx.translate(Math.round(c.x),Math.round(c.y));
  for(let j=0;j<3;j++){const a=age-j*.2;if(a>0&&a<1.2){const k=a/1.2;ctx.strokeStyle=rg(T[j%2],(1-k)*.85);ctx.lineWidth=5*(1-k)+1;
   ctx.beginPath();ctx.ellipse(0,14,c.r*(1+k*6),c.r*(.4+k*2),0,0,6.283);ctx.stroke()}}
  if(age<.4){ctx.fillStyle=rg(T[1],(1-age/.4)*.45);ctx.fillRect(-c.r*.6,-280,c.r*1.2,294)}
  if(c.cfg){const M=META[c.cfg.key],Hh=Math.max(84,c.r*2.7),fa=Math.min(1,(c.life-age)/.7);let df=null,al=fa,fl=0;
   if(c.fr)df=c.fr[Math.min(c.fr.length-1,Math.floor(age/M.dt[2]))];
   else{al=Math.max(0,1-age/1.3);fl=(Math.sin(age*40)>0?.5:0);ctx.translate(Math.sin(age*60)*3,age*8);const k=1-age*.12;ctx.scale(k,k)}
   spr(c.cfg,Hh,c.fx,'idle',{age:0,off:0},c.t0,fl,al,0,null,df,null)}
  ctx.restore()}}
const _dnc=window.drawNaCorpses;
window.drawNaCorpses=function(){_dnc();try{bxCorpses()}catch(_){}};
/* ikon codex / dialog boss */
const _ni=window.naIcon;
window.naIcon=function(def,size,g){
 if(def.boss){if(def._ti===undefined)def._ti=ET.indexOf(def);const c=naCfg(def._ti,def);
  if(c&&META[c.key]){if(!BX.ready)return false;const M=META[c.key],s=sh(c.key,c.deg),ic=M.ic;
   const k=Math.min((size-8)/ic[2],(size-8)/ic[3]),w=ic[2]*k,h=ic[3]*k;g.imageSmoothingEnabled=!!M.st;
   const sx=M.st?0:ic[0],sy=M.st?0:ic[1];g.drawImage(s,sx,sy,ic[2],ic[3],Math.round((size-w)/2),Math.round((size-h)/2),Math.round(w),Math.round(h));return true}}
 return _ni(def,size,g)};
const _nde=window.naDrawEnemy;
window.naDrawEnemy=function(e,cfg){if(META[cfg.key])return bxDraw(e,cfg);return _nde(e,cfg)};
window.__bxNoAura=true;
}catch(err){console.error('BOSS+ asset pack gagal dimuat:',err)}})();
